{
    [Header("Target UI Image to detect collision with")]
    public RectTransform targetRectTransform;

    [Header("Prefab to instantiate")]
    public GameObject prefabToInstantiate;

    [Header("Parent Transform for instantiated prefab")]
    public Transform prefabParentTransform;

    private RectTransform rectTransform;

    void Awake()
    {
        rectTransform = GetComponent<RectTransform>();

        if (rectTransform == null)
        {
            Debug.LogError("This script must be attached to a GameObject with a RectTransform.");
            enabled = false;
            return;
        }

        if (targetRectTransform == null)
        {
            Debug.LogError("Target RectTransform is not assigned.");
            enabled = false;
            return;
        }

        if (prefabToInstantiate == null)
        {
            Debug.LogError("Prefab to instantiate is not assigned.");
            enabled = false;
            return;
        }

        if (prefabParentTransform == null)
        {
            Debug.LogWarning("Prefab parent transform is not assigned. Using current object's parent.");
            prefabParentTransform = transform.parent;
        }
    }

    void Update()
    {
        if (IsRectTransformOverlapping(rectTransform, targetRectTransform))
        {
            GameObject ICO = Instantiate(prefabToInstantiate, prefabParentTransform);
            ICO.GetComponent<Image>().sprite = gameObject.GetComponent<Image>().sprite;
            ICO.name = gameObject.name;

            Destroy(gameObject);
        }
    }

    // Checks if two UI RectTransforms overlap
    public static bool IsRectTransformOverlapping(RectTransform rect1, RectTransform rect2)
    {
        Rect rectA = GetScreenRect(rect1);
        Rect rectB = GetScreenRect(rect2);

        return rectA.Overlaps(rectB);
    }

    // Convert RectTransform to Screen Space Rect
    public static Rect GetScreenRect(RectTransform rectTransform)
    {
        Vector3[] corners = new Vector3[4];
        rectTransform.GetWorldCorners(corners);

        // Bottom-left and top-right corners in screen space
        Vector3 bottomLeft = RectTransformUtility.WorldToScreenPoint(null, corners[0]);
        Vector3 topRight = RectTransformUtility.WorldToScreenPoint(null, corners[2]);

        return new Rect(bottomLeft, topRight - bottomLeft);
    }
}

